import{_ as r,H as a,f as t,i as l}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"加餐1｜特别福利：陶辉视频课精选","description":"","frontmatter":{},"headers":[{"level":2,"title":"第1节","slug":"第1节","link":"#第1节","children":[]},{"level":2,"title":"第2节","slug":"第2节","link":"#第2节","children":[]},{"level":2,"title":"第3节","slug":"第3节","link":"#第3节","children":[]}],"relativePath":"系统性能调优必知必会/加餐1｜特别福利：陶辉视频课精选.md","filePath":"系统性能调优必知必会/加餐1｜特别福利：陶辉视频课精选.md","lastUpdated":1779821570000}'),o={name:"系统性能调优必知必会/加餐1｜特别福利：陶辉视频课精选.md"};function i(n,e,_,h,s,p){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="加餐1-特别福利-陶辉视频课精选" tabindex="-1">加餐1｜特别福利：陶辉视频课精选 <a class="header-anchor" href="#加餐1-特别福利-陶辉视频课精选" aria-label="Permalink to &quot;加餐1｜特别福利：陶辉视频课精选&quot;">​</a></h1><p>你好，我是陶辉。</p><p>不知道你的期中考试成绩如何呢？是否发现了一些新的问题？成绩好的同学请继续努力了，咱们还有一半的课程未学，希望你能一如既往地跟着我深挖系统性能，这门课的内容设计是由浅入深的，第三、四模块会重点往集群方向转了，内容相对会更加烧脑。成绩略差的同学也不要气馁，就像我上节课说的，问题驱动是一种很好的学习方式，查漏补缺才是这场期中考试的目的。</p><p>聊完考试，我就来兑现承诺了，精选3节我的视频课作为福利送给你，它们来自 <a href="https://time.geekbang.org/course/detail/100026801-93596" target="_blank" rel="noreferrer">《Web协议详解与抓包实战》</a>，这3节课都是与咱们专栏有强关联的。</p><p>我还记得在开篇词中有位同学问我，学习咱们专栏需要哪些基础？我是这么回复的：</p><ol><li>对操作系统的原理有简单的了解，比如，文件是怎么读取的，HTTP请求是怎么发送和接收的；</li><li>对网络协议要有所了解，毕竟分布式系统就是靠网络将操作系统上的进程连接在一起。这块《Web协议详解与抓包实战》可以先学下。</li><li>大致知道什么是分布式系统，这块网上的文章有很多。</li></ol><p>其中第1点和第3点，我想还是很容易的，所以我就在第2点上为你加码了。以下就是3节视频课，你可以直接点击观看。</p><h2 id="第1节" tabindex="-1">第1节 <a class="header-anchor" href="#第1节" aria-label="Permalink to &quot;第1节&quot;">​</a></h2><p>与 <a href="https://time.geekbang.org/column/article/235302" target="_blank" rel="noreferrer">第7课</a> 有联系的 <a href="https://time.geekbang.org/course/detail/175-134405" target="_blank" rel="noreferrer">《Web协议详解与抓包实战》第117课</a>。我在第7课讲解组播时，有推荐你如果想要进一步了解组播的细节，可以观看以下视频课。</p><h2 id="第2节" tabindex="-1">第2节 <a class="header-anchor" href="#第2节" aria-label="Permalink to &quot;第2节&quot;">​</a></h2><p>与 <a href="https://time.geekbang.org/column/article/241632" target="_blank" rel="noreferrer">第14课</a> 有联系的 <a href="https://time.geekbang.org/course/detail/175-104932" target="_blank" rel="noreferrer">《Web协议详解与抓包实战》第51课</a>。我在第14课讲解用 Chrome 浏览器配合 Wireshark 解密消息，可以帮助你分析 TLS 协议的细节时，具体的操作方法有推荐你观看以下视频课。</p><h2 id="第3节" tabindex="-1">第3节 <a class="header-anchor" href="#第3节" aria-label="Permalink to &quot;第3节&quot;">​</a></h2><p>与 <a href="https://time.geekbang.org/column/article/242667" target="_blank" rel="noreferrer">第15课</a> 有联系的 <a href="https://time.geekbang.org/course/detail/175-93594" target="_blank" rel="noreferrer">《Web协议详解与抓包实战》第9课</a>。第15课我们介绍了 Chrome 浏览器开发者工具的 Network 面板，通过它可以快速判断各站点使用了哪些HTTP性能优化技术，有关 Network 面板的详细用法，我推荐你观看以下视频课。</p><p>今天的特别福利就到这里，这3节视频课对于你学习咱们专栏有一定的辅助作用，希望你能把它作为拓展认真学完。如果你有更多想要了解的内容和期待的学习资料，欢迎在留言区中提出。</p>',14)])])}const g=r(o,[["render",i]]);export{d as __pageData,g as default};
